import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { events, eventCategories, eventAreas } from '../../mocks/events';
import EventCard from './components/EventCard';
import FeaturedEventBanner from './components/FeaturedEventBanner';
import EventCalendar from './components/EventCalendar';
import GlobalHeader from '../../components/feature/GlobalHeader';
import GlobalFooter from '../../components/feature/GlobalFooter';
import Breadcrumb from '../../components/feature/Breadcrumb';

export default function EventsPage() {
  const navigate = useNavigate();
  const [selectedCategory, setSelectedCategory] = useState('すべて');
  const [selectedArea, setSelectedArea] = useState('すべて');
  const [viewMode, setViewMode] = useState<'list' | 'calendar'>('list');

  const featuredEvents = events.filter(event => event.featured);
  
  const filteredEvents = useMemo(() => {
    return events.filter(event => {
      const categoryMatch = selectedCategory === 'すべて' || event.category === selectedCategory;
      const areaMatch = selectedArea === 'すべて' || event.area === selectedArea;
      return categoryMatch && areaMatch;
    });
  }, [selectedCategory, selectedArea]);

  const handleEventClick = (eventId: number) => {
    const element = document.getElementById(`event-${eventId}`);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* 共通ヘッダー */}
      <GlobalHeader showBanner={false} showSearch={false} />

      {/* パンくずリスト */}
      <Breadcrumb items={[{ label: 'イベントNAVI' }]} />

      {/* Hero Section */}
      <div className="bg-gradient-to-r from-orange-600 to-red-600 text-white py-16">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex items-center gap-3 mb-4">
            <i className="ri-calendar-event-line text-4xl"></i>
            <h1 className="text-4xl font-bold">イベントNAVI</h1>
          </div>
          <p className="text-xl text-white/90">
            全国のカーイベント情報をチェック！オートショー、ミーティング、走行会など盛りだくさん
          </p>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Featured Events */}
        {featuredEvents.length > 0 && (
          <div className="mb-12">
            <h2 className="text-2xl font-bold text-gray-900 mb-6 flex items-center gap-2">
              <i className="ri-star-line text-orange-500"></i>
              注目のイベント
            </h2>
            <div className="space-y-6">
              {featuredEvents.map(event => (
                <FeaturedEventBanner key={event.id} event={event} />
              ))}
            </div>
          </div>
        )}

        {/* View Mode Toggle */}
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-gray-900">イベント一覧</h2>
          <div className="flex gap-2 bg-white rounded-lg p-1 shadow-sm">
            <button
              onClick={() => setViewMode('list')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap cursor-pointer ${
                viewMode === 'list'
                  ? 'bg-gray-900 text-white'
                  : 'text-gray-600 hover:bg-gray-100'
              }`}
            >
              <i className="ri-list-check mr-2"></i>
              リスト表示
            </button>
            <button
              onClick={() => setViewMode('calendar')}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap cursor-pointer ${
                viewMode === 'calendar'
                  ? 'bg-gray-900 text-white'
                  : 'text-gray-600 hover:bg-gray-100'
              }`}
            >
              <i className="ri-calendar-line mr-2"></i>
              カレンダー表示
            </button>
          </div>
        </div>

        <div className="flex flex-col lg:flex-row gap-8">
          {/* Filters Sidebar */}
          <div className="lg:w-64 flex-shrink-0">
            <div className="bg-white rounded-lg shadow-sm p-6 sticky top-4">
              <h3 className="text-lg font-bold text-gray-900 mb-4">絞り込み</h3>
              
              {/* Category Filter */}
              <div className="mb-6">
                <h4 className="text-sm font-semibold text-gray-700 mb-3">カテゴリ</h4>
                <div className="space-y-2">
                  {eventCategories.map(category => (
                    <label key={category} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="radio"
                        name="category"
                        checked={selectedCategory === category}
                        onChange={() => setSelectedCategory(category)}
                        className="w-4 h-4 text-orange-600 cursor-pointer"
                      />
                      <span className="text-sm text-gray-700">{category}</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* Area Filter */}
              <div>
                <h4 className="text-sm font-semibold text-gray-700 mb-3">エリア</h4>
                <div className="space-y-2">
                  {eventAreas.map(area => (
                    <label key={area} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="radio"
                        name="area"
                        checked={selectedArea === area}
                        onChange={() => setSelectedArea(area)}
                        className="w-4 h-4 text-orange-600 cursor-pointer"
                      />
                      <span className="text-sm text-gray-700">{area}</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* Reset Button */}
              <button
                onClick={() => {
                  setSelectedCategory('すべて');
                  setSelectedArea('すべて');
                }}
                className="w-full mt-6 px-4 py-2 bg-gray-100 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-200 transition-colors whitespace-nowrap cursor-pointer"
              >
                <i className="ri-refresh-line mr-2"></i>
                リセット
              </button>
            </div>
          </div>

          {/* Main Content */}
          <div className="flex-1">
            {viewMode === 'calendar' ? (
              <EventCalendar 
                events={filteredEvents.map(e => ({
                  id: e.id,
                  title: e.title,
                  date: e.date,
                  category: e.category
                }))}
                onEventClick={handleEventClick}
              />
            ) : (
              <>
                <div className="mb-4 text-sm text-gray-600">
                  {filteredEvents.length}件のイベントが見つかりました
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {filteredEvents.map(event => (
                    <div key={event.id} id={`event-${event.id}`}>
                      <EventCard event={event} />
                    </div>
                  ))}
                </div>
              </>
            )}

            {filteredEvents.length === 0 && (
              <div className="text-center py-16">
                <i className="ri-calendar-close-line text-6xl text-gray-300 mb-4"></i>
                <p className="text-gray-500">条件に合うイベントが見つかりませんでした</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* フッター */}
      <GlobalFooter />
    </div>
  );
}