import { Link } from 'react-router-dom';

interface FeaturedEventBannerProps {
  event: {
    id: number;
    title: string;
    date: string;
    endDate: string;
    area: string;
    prefecture: string;
    venue: string;
    category: string;
    description: string;
    image: string;
    price: string;
    organizer: string;
  };
}

export default function FeaturedEventBanner({ event }: FeaturedEventBannerProps) {
  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
  };

  return (
    <div className="bg-gradient-to-r from-orange-500 to-red-500 rounded-xl overflow-hidden shadow-lg">
      <div className="flex flex-col md:flex-row">
        <div className="md:w-1/2 relative w-full h-64 md:h-auto">
          <img
            src={event.image}
            alt={event.title}
            className="w-full h-full object-cover object-top"
          />
          <div className="absolute top-4 left-4 bg-white px-4 py-2 rounded-full text-sm font-bold text-orange-600">
            注目イベント
          </div>
        </div>
        <div className="md:w-1/2 p-8 text-white">
          <div className="inline-block bg-white/20 px-3 py-1 rounded-full text-sm font-medium mb-4">
            {event.category}
          </div>
          <h2 className="text-3xl font-bold mb-4">{event.title}</h2>
          <div className="space-y-3 mb-6">
            <div className="flex items-center gap-3">
              <i className="ri-calendar-line text-xl"></i>
              <span className="text-lg">
                {formatDate(event.date)}
                {event.date !== event.endDate && ` - ${formatDate(event.endDate)}`}
              </span>
            </div>
            <div className="flex items-center gap-3">
              <i className="ri-map-pin-line text-xl"></i>
              <span className="text-lg">{event.prefecture} {event.venue}</span>
            </div>
            <div className="flex items-center gap-3">
              <i className="ri-ticket-line text-xl"></i>
              <span className="text-lg">{event.price}</span>
            </div>
          </div>
          <p className="text-white/90 mb-6 leading-relaxed">
            {event.description}
          </p>
          <Link
            to={`/events/${event.id}`}
            className="inline-block px-6 py-3 bg-white text-orange-600 font-bold rounded-lg hover:bg-gray-100 transition-colors whitespace-nowrap cursor-pointer"
          >
            イベント詳細を見る
          </Link>
        </div>
      </div>
    </div>
  );
}