import { Link } from 'react-router-dom';

interface EventCardProps {
  event: {
    id: number;
    title: string;
    date: string;
    endDate: string;
    area: string;
    prefecture: string;
    venue: string;
    category: string;
    description: string;
    image: string;
    price: string;
    organizer: string;
  };
}

export default function EventCard({ event }: EventCardProps) {
  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return `${date.getMonth() + 1}/${date.getDate()}`;
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'オートショー':
        return 'bg-purple-100 text-purple-700';
      case 'ミーティング':
        return 'bg-blue-100 text-blue-700';
      case '走行会':
        return 'bg-red-100 text-red-700';
      case 'フリマ':
        return 'bg-green-100 text-green-700';
      default:
        return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="bg-white rounded-lg overflow-hidden shadow-sm hover:shadow-md transition-shadow">
      <div className="relative w-full h-48">
        <img
          src={event.image}
          alt={event.title}
          className="w-full h-full object-cover object-top"
        />
        <div className={`absolute top-3 left-3 px-3 py-1 rounded-full text-sm font-medium ${getCategoryColor(event.category)}`}>
          {event.category}
        </div>
      </div>
      <div className="p-5">
        <div className="flex items-center gap-2 text-sm text-gray-600 mb-2">
          <i className="ri-calendar-line"></i>
          <span>
            {formatDate(event.date)}
            {event.date !== event.endDate && ` - ${formatDate(event.endDate)}`}
          </span>
        </div>
        <h3 className="text-lg font-bold text-gray-900 mb-2 line-clamp-2">
          {event.title}
        </h3>
        <div className="flex items-start gap-2 text-sm text-gray-600 mb-3">
          <i className="ri-map-pin-line mt-0.5"></i>
          <div>
            <div>{event.prefecture}</div>
            <div>{event.venue}</div>
          </div>
        </div>
        <p className="text-sm text-gray-600 mb-4 line-clamp-2">
          {event.description}
        </p>
        <div className="flex items-center justify-between pt-4 border-t border-gray-100">
          <div className="text-sm">
            <div className="text-gray-500">参加費</div>
            <div className="font-semibold text-gray-900">{event.price}</div>
          </div>
          <Link
            to={`/events/${event.id}`}
            className="px-4 py-2 bg-gray-900 text-white text-sm font-medium rounded-lg hover:bg-gray-800 transition-colors whitespace-nowrap cursor-pointer"
          >
            詳細を見る
          </Link>
        </div>
      </div>
    </div>
  );
}